#!/bin/bash
#
# Run the TACLeBench binaries as Jailhouse APU inmates on the ZCU104 and record
# their execution time, measured by the inmate itself from the ZynqMP system
# counter and handed over through a one-word shared memory mailbox.
#
# Handshake (the inmate half lives in the wrapper generated by
# compile_benchmark_wrap.sh):
#
#   root                                     inmate
#   ----                                     ------
#   write INITIAL (0xDEADBEEF)
#   create / load / start cell
#                                            read counter -> start_time
#                                            write start_time to mailbox
#   see mailbox != INITIAL -> record start
#   write INTERMEDIATE (0xBEEFDEAD)
#                                            run the benchmark
#                                            read counter -> end_time
#                                            spin until mailbox == INTERMEDIATE
#                                            write end_time to mailbox
#   see mailbox != INTERMEDIATE -> record end
#   destroy cell
#
# Output: one file per benchmark, results_<name>.bin.txt, with lines
#   "Iteration N: Start value: 0x..., End value: 0x..."
# which is the format expected by extract_time.sh.
#
# Usage: ./external_script_shmem.sh [-b bench1 bench2 ...] [-o results_dir]

ITERATIONS=31
INITIAL_VALUE=0xDEADBEEF
INTERMEDIATE_VALUE=0xBEEFDEAD
ADDRESS=0x3ad00000                                    # must match the cell's SHM region
BAREMETAL_INMATE_CELL="zynqmp-zcu104-APU-inmate-demo.cell"
CELL_NAME="inmate-demo-APU"
BIN_FILE_DIR="/root/taclebench/executables/APU_jailhouse/shmem"
RESULTS_DIR="/root/taclebench/results/APU_jailhouse/shmem"
TIMEOUT_SECONDS=30
TIMEOUT_THRESHOLD=3
POLL_INTERVAL=0.5                                     # mailbox polling period

# jailhouse is not on the default PATH
if [[ -r /etc/profile.d/jailhouse_path.sh ]]; then
    . /etc/profile.d/jailhouse_path.sh
fi

function show_help() {
    echo "Usage: $0 [-b benchmark1 benchmark2 ...] [-o results_dir]"
    echo "  -b          run only the specified benchmarks (names without .bin)"
    echo "  -o          write results into this directory instead of $RESULTS_DIR"
    echo "  -h, --help  show this help message and exit"
    exit 0
}

SELECTED_BENCHMARKS=()
while [[ $# -gt 0 ]]; do
    case "$1" in
        -h|--help) show_help ;;
        -o) RESULTS_DIR="$2"; shift 2 ;;
        -b) shift
            while [[ $# -gt 0 && "$1" != -* ]]; do
                SELECTED_BENCHMARKS+=("$1"); shift
            done ;;
        *)  echo "Unknown argument: $1" >&2; exit 1 ;;
    esac
done

if [[ -z "${JAILHOUSE_DIR:-}" ]]; then
    echo "Error: JAILHOUSE_DIR is not set and /etc/profile.d/jailhouse_path.sh was not readable." >&2
    exit 1
fi

CELL_CONFIG="${JAILHOUSE_DIR}/configs/arm64/${BAREMETAL_INMATE_CELL}"
if [[ ! -f "$CELL_CONFIG" ]]; then
    echo "Error: cell configuration $CELL_CONFIG not found." >&2
    exit 1
fi

if ! jailhouse cell list >/dev/null 2>&1; then
    echo "Error: the Jailhouse hypervisor does not seem to be enabled." >&2
    echo "Start it with ./scripts_jailhouse_zcu104/jailhouse_setup/jailhouse_start.sh" >&2
    exit 1
fi

mkdir -p "$RESULTS_DIR"

# Only .bin files: the executables directory may also hold objects.
ALL_BENCHMARKS=$(find "$BIN_FILE_DIR" -type f -name '*.bin' | xargs -n 1 basename | sort)

if [[ -z "$ALL_BENCHMARKS" ]]; then
    echo "No Benchmark binaries found within $BIN_FILE_DIR. Exiting..."
    exit 1
fi

echo "Found $(echo "$ALL_BENCHMARKS" | wc -l) benchmarks."

if [[ ${#SELECTED_BENCHMARKS[@]} -gt 0 ]]; then
    BENCHMARKS=()
    for BENCH in "${SELECTED_BENCHMARKS[@]}"; do
        if [[ -f "$BIN_FILE_DIR/$BENCH.bin" ]]; then
            BENCHMARKS+=("$BENCH.bin")
        else
            echo "Error: Benchmark '$BENCH.bin' not found in $BIN_FILE_DIR." >&2
            exit 1
        fi
    done
else
    BENCHMARKS=($ALL_BENCHMARKS)
fi

echo "Results directory: $RESULTS_DIR"

# Leave no cell behind from an interrupted previous run.
jailhouse cell destroy "$CELL_NAME" >/dev/null 2>&1

read_mailbox() {
    devmem $ADDRESS 32 2>/dev/null | grep -oE '0x[0-9A-Fa-f]+$'
}

# Poll the mailbox until it moves away from $1. Echoes the new value, or
# nothing on timeout.
wait_for_change() {
    local previous=$1 value deadline=$((SECONDS + TIMEOUT_SECONDS))
    while (( SECONDS < deadline )); do
        value=$(read_mailbox)
        if [[ -z "$value" ]]; then
            echo "Error: Failed to read memory address." >&2
            return 1
        fi
        if [[ "$value" != "$previous" ]]; then
            echo "$value"
            return 0
        fi
        sleep $POLL_INTERVAL
    done
    return 1
}

BENCHMARK_COUNTER=0
FAILED_BENCHMARKS=()

for BIN_FILE in ${BENCHMARKS[@]}; do
    BENCHMARK_COUNTER=$((BENCHMARK_COUNTER + 1))
    echo "Processing benchmark $BIN_FILE ($BENCHMARK_COUNTER/${#BENCHMARKS[@]})..."

    RESULT_FILE="$RESULTS_DIR/results_${BIN_FILE}.txt"
    : > "$RESULT_FILE"

    TIMEOUT_COUNT=0

    for ((ITER=1; ITER<=ITERATIONS; ITER++)); do
        echo "Iteration $ITER/$ITERATIONS for benchmark $BIN_FILE..."

        if ! devmem $ADDRESS 32 $INITIAL_VALUE; then
            echo "Error: Failed to write initial value to memory." >&2
            continue
        fi

        if ! jailhouse cell create "$CELL_CONFIG"; then
            echo "Error: Failed to create Jailhouse cell." >&2
            continue
        fi

        if ! jailhouse cell load $CELL_NAME $BIN_FILE_DIR/$BIN_FILE; then
            echo "Error: Failed to load binary into Jailhouse cell." >&2
            jailhouse cell destroy $CELL_NAME
            continue
        fi

        if ! jailhouse cell start $CELL_NAME; then
            echo "Error: Failed to start Jailhouse cell." >&2
            jailhouse cell destroy $CELL_NAME
            continue
        fi

        # The inmate publishes its start timestamp, then blocks until it sees
        # the acknowledgement, so the wait below is not part of the measurement.
        if ! START_VALUE=$(wait_for_change "$INITIAL_VALUE"); then
            echo "Timeout while waiting for start value." >&2
            jailhouse cell destroy $CELL_NAME
            TIMEOUT_COUNT=$((TIMEOUT_COUNT + 1))
            (( TIMEOUT_COUNT >= TIMEOUT_THRESHOLD )) && break
            continue
        fi
        echo "Value changed! Start value: $START_VALUE"

        if ! devmem $ADDRESS 32 $INTERMEDIATE_VALUE; then
            echo "Error: Failed to write intermediate value to memory." >&2
            jailhouse cell destroy $CELL_NAME
            continue
        fi

        if ! END_VALUE=$(wait_for_change "$INTERMEDIATE_VALUE"); then
            echo "Timeout while waiting for end value." >&2
            jailhouse cell destroy $CELL_NAME
            TIMEOUT_COUNT=$((TIMEOUT_COUNT + 1))
            (( TIMEOUT_COUNT >= TIMEOUT_THRESHOLD )) && break
            continue
        fi
        echo "Value changed! End value: $END_VALUE"

        jailhouse cell destroy $CELL_NAME

        sync
        echo 3 > /proc/sys/vm/drop_caches
        sleep 2

        echo "Iteration $ITER: Start value: $START_VALUE, End value: $END_VALUE" >> "$RESULT_FILE"
    done

    if (( TIMEOUT_COUNT >= TIMEOUT_THRESHOLD )); then
        echo "Benchmark $BIN_FILE failed due to excessive timeouts. Moving to next benchmark."
        FAILED_BENCHMARKS+=("$BIN_FILE")
        continue
    fi

    echo "Benchmark $BIN_FILE completed. Results saved to $RESULT_FILE."
done

if [[ ${#FAILED_BENCHMARKS[@]} -gt 0 ]]; then
    echo "The following benchmarks failed due to excessive timeouts:"
    for FAILED in "${FAILED_BENCHMARKS[@]}"; do
        echo "- $FAILED"
    done
else
    echo "All benchmarks completed successfully."
fi

echo "Script completed. All benchmarks executed."
